app.get("/reviews", async (c) => {
  const db = c.get("db");
  const poiId = Number(c.req.query("poi_id"));
  if (!Number.isFinite(poiId) || poiId <= 0) {
    return jsonError(c, 400, "Valid poi_id is required", "INVALID_POI_ID");
  }

  const poi = await db.select().from(schema.pois).where(eq(schema.pois.id, poiId)).get();
  if (!poi) return jsonError(c, 404, "POI not found", "POI_NOT_FOUND");

  const profile = await getProfileByToken(c, db);

  try {
    const reviewsList = await db
      .select({
        ...getTableColumns(schema.reviews),
        profile_display_name: schema.profiles.display_name,
        profile_avatar_url: schema.profiles.avatar_url,
      })
      .from(schema.reviews)
      .leftJoin(schema.profiles, eq(schema.reviews.user_id, schema.profiles.id))
      .where(and(eq(schema.reviews.poi_id, poiId), isNull(schema.reviews.deleted_at)))
      .orderBy(desc(schema.reviews.updated_at))
      .all();

    if (reviewsList.length === 0) return c.json([]);

    const reviewIds = reviewsList.map((review) => review.id);
    const voteRows =
      reviewIds.length === 0
        ? []
        : await db
            .select({
              review_id: schema.votes.review_id,
              user_id: schema.votes.user_id,
              vote: schema.votes.vote,
            })
            .from(schema.votes)
            .where(inArray(schema.votes.review_id, reviewIds))
            .all();

    const voteSummaryByReviewId = new Map<number, { vote_count: number; user_vote: number | null }>();

    for (const vote of voteRows) {
      const summary = voteSummaryByReviewId.get(vote.review_id) ?? {
        vote_count: 0,
        user_vote: null,
      };
      summary.vote_count += vote.vote;
      if (profile && vote.user_id === profile.id) {
        summary.user_vote = vote.vote;
      }
      voteSummaryByReviewId.set(vote.review_id, summary);
    }

    const result = reviewsList.map((review) => {
      const summary = voteSummaryByReviewId.get(review.id);
      return {
        ...review,
        vote_count: summary?.vote_count ?? 0,
        user_vote: summary?.user_vote ?? null,
      };
    });

    return c.json(result);
  } catch (error) {
    return jsonError(c, 500, `Failed to load reviews: ${String(error)}`, "REVIEW_LOAD_FAILED");
  }
});

app.post("/reviews", async (c) => {
  const db = c.get("db");
  const auth = await requireCompletedProfile(c, db);
  if (auth instanceof Response) return auth;

  const body = await parseBody(c);
  if (!body) return jsonError(c, 400, "Invalid JSON body", "INVALID_JSON");

  const poiId = Number(body.poi_id);
  const rating = Number(body.rating);
  const content = typeof body.content === "string" ? body.content : null;
  const features =
    typeof body.features === "string"
      ? body.features
      : Array.isArray(body.features)
        ? JSON.stringify(body.features)
        : null;

  if (!Number.isFinite(poiId) || poiId <= 0) {
    return jsonError(c, 400, "Valid poi_id is required", "INVALID_POI_ID");
  }
  if (!Number.isFinite(rating) || rating < 1 || rating > 5) {
    return jsonError(c, 400, "rating must be between 1 and 5", "INVALID_RATING");
  }

  const poi = await db.select().from(schema.pois).where(eq(schema.pois.id, poiId)).get();
  if (!poi) return jsonError(c, 404, "POI not found", "POI_NOT_FOUND");

  const existingReview = await db
    .select()
    .from(schema.reviews)
    .where(and(eq(schema.reviews.user_id, auth.profile.id), eq(schema.reviews.poi_id, poiId)))
    .get();

  if (existingReview) {
    const updated = await db
      .update(schema.reviews)
      .set({
        rating,
        features,
        content,
        deleted_at: null,
        updated_at: new Date(),
      })
      .where(eq(schema.reviews.id, existingReview.id))
      .returning();

    return c.json(updated[0] ?? null);
  }

  const inserted = await db
    .insert(schema.reviews)
    .values({
      user_id: auth.profile.id,
      poi_id: poiId,
      rating,
      features,
      content,
    })
    .returning();

  return c.json(inserted[0] ?? null);
});

app.put("/reviews/:id", async (c) => {
  const db = c.get("db");
  const auth = await requireCompletedProfile(c, db);
  if (auth instanceof Response) return auth;

  const reviewId = Number(c.req.param("id"));
  if (!Number.isFinite(reviewId)) {
    return jsonError(c, 400, "Invalid review id", "INVALID_REVIEW_ID");
  }

  const body = await parseBody(c);
  if (!body) return jsonError(c, 400, "Invalid JSON body", "INVALID_JSON");

  const rating = Number(body.rating);
  const content = typeof body.content === "string" ? body.content : null;
  const features =
    typeof body.features === "string"
      ? body.features
      : Array.isArray(body.features)
        ? JSON.stringify(body.features)
        : null;

  if (!Number.isFinite(rating) || rating < 1 || rating > 5) {
    return jsonError(c, 400, "rating must be between 1 and 5", "INVALID_RATING");
  }

  const review = await db
    .select()
    .from(schema.reviews)
    .where(eq(schema.reviews.id, reviewId))
    .get();

  if (!review || review.user_id !== auth.profile.id) {
    return jsonError(c, 403, "Forbidden", "FORBIDDEN");
  }

  const updated = await db
    .update(schema.reviews)
    .set({ rating, features, content, updated_at: new Date() })
    .where(eq(schema.reviews.id, reviewId))
    .returning();

  return c.json(updated[0] ?? null);
});

